const { remote } = require('~/.node/lib/node_modules/webdriverio');

const CAPS = {
  platformName: 'iOS',
  'appium:automationName': 'XCUITest',
  'appium:udid': 'DB3B1E97-CCA1-490A-B46C-7D4D5F627CAF',
  'appium:bundleId': 'xyz.blueskyweb.app',
  'appium:noReset': true,
  'appium:autoLaunch': false,
  'appium:shouldTerminateApp': false,
  'appium:newCommandTimeout': 300,
};

(async () => {
  const browser = await remote({ protocol: 'http', hostname: '127.0.0.1', port: 4723, path: '/', capabilities: CAPS, logLevel: 'error' });
  await browser.activateApp('xyz.blueskyweb.app');

  let ready = false;
  for (let i = 0; i < 20; i++) {
    await browser.pause(1500);
    const src = await browser.getPageSource();
    if (src.includes('followingFeedPage-feed-flatlist') && src.includes('composeFAB')) {
      const m = src.match(/followingFeedPage-feed-flatlist[\s\S]{0,4000}?height="(\d+)" index="1"/);
      ready = true;
      console.log('feed ready at iteration', i);
      break;
    }
    console.log('waiting for feed...', i);
  }
  if (!ready) { console.log('feed not ready, aborting'); await browser.deleteSession(); process.exit(2); }

  await browser.pause(1000);
  await browser.execute('mobile: tap', { x: 82, y: 588 });
  await browser.pause(3000);
  const src = await browser.getPageSource();
  require('fs').writeFileSync('/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/source5.xml', src);
  console.log('saved source, length', src.length, 'hasReply:', /reply|Reply|Write your/.test(src));
  await browser.deleteSession();
})().catch(e => { console.error('ERR', e.message); process.exit(1); });

const { remote } = require('~/.node/lib/node_modules/webdriverio');

const CAPS = {
  platformName: 'iOS',
  'appium:automationName': 'XCUITest',
  'appium:udid': 'DB3B1E97-CCA1-490A-B46C-7D4D5F627CAF',
  'appium:bundleId': 'xyz.blueskyweb.app',
  'appium:noReset': true,
  'appium:autoLaunch': false,
  'appium:shouldTerminateApp': false,
  'appium:newCommandTimeout': 300,
};
const OUT = '/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode';

(async () => {
  const browser = await remote({ protocol: 'http', hostname: '127.0.0.1', port: 4723, path: '/', capabilities: CAPS, logLevel: 'error' });
  await browser.activateApp('xyz.blueskyweb.app');
  await browser.pause(3000);

  let src = await browser.getPageSource();
  let hasComposer = src.includes('composerTextInput');

  if (!hasComposer) {
    console.log('composer not open; waiting for feed and tapping reply');
    for (let i = 0; i < 20; i++) {
      await browser.pause(1500);
      src = await browser.getPageSource();
      if (src.includes('followingFeedPage-feed-flatlist') && src.includes('composeFAB')) break;
    }
    await browser.pause(1000);
    await browser.execute('mobile: tap', { x: 82, y: 588 });
    await browser.pause(3000);
    src = await browser.getPageSource();
    hasComposer = src.includes('composerTextInput');
  }
  if (!hasComposer) {
    require('fs').writeFileSync(OUT + '/fail.xml', src);
    console.log('FAIL: composer did not open');
    await browser.deleteSession();
    process.exit(2);
  }

  const input = await browser.$('~composerTextInput');
  await input.click();
  await browser.pause(500);
  await input.setValue('nice one');
  await browser.pause(1000);

  const pub = await browser.$('~composerPublishBtn');
  await pub.waitForEnabled({ timeout: 10000 });
  await pub.click();
  console.log('clicked publish');
  await browser.pause(4000);

  src = await browser.getPageSource();
  require('fs').writeFileSync(OUT + '/source6.xml', src);
  console.log('done, length', src.length, 'stillComposer:', src.includes('composerTextInput'));
  await browser.deleteSession();
})().catch(e => { console.error('ERR', e.message); process.exit(1); });

